"""Единая конфигурация пакета: пути к данным и все настраиваемые константы алгоритма.

Для интегратора:
    * Все «магические числа» алгоритма собраны здесь. Менять их в других модулях не нужно —
      функции берут значения по умолчанию отсюда, но почти везде их можно переопределить
      аргументом при вызове.
    * Путь к данным (исходные снимки, патчи, маски Cellpose) задаётся переменной окружения
      ``IMBP_DATA_DIR``. По умолчанию используется соседняя папка ``../ML``.
    * Для работы ПО (инференса) данные НЕ нужны — нужен только файл обученной модели
      ``models/slic_params_rf.joblib``. Путь к нему можно переопределить через ``IMBP_MODEL_PATH``.
"""

from __future__ import annotations

import os
from pathlib import Path

# ---------------------------------------------------------------------------
# Пути
# ---------------------------------------------------------------------------

# Корень проекта imbp/ (config.py лежит в imbp/src/imbp/).
PROJECT_ROOT = Path(__file__).resolve().parents[2]

# Папка с исходными данными исследования (не копируется в imbp, см. README).
DATA_DIR = Path(os.environ.get("IMBP_DATA_DIR", PROJECT_ROOT.parent / "ML"))
RAW_IMAGES_DIR = DATA_DIR / "raw_images"            # исходные снимки микроскопа (.bmp/.jpg)
PATCHES_DIR = DATA_DIR / "dataset_patches"          # все патчи 3×4 (img_XXXX.png)
SUBSET_IMAGES_DIR = DATA_DIR / "train_subset_images"  # случайная подвыборка патчей для обучения
FILENAME_MAPPING_CSV = DATA_DIR / "filename_mapping.csv"  # img_XXXX.png -> имя исходного патча

# Эталонная разметка (псевдоразметка нейросетью) — по ней обучаются модели и считаются метрики.
#   cellpose       — Cellpose cyto2 (как в курсовой, scripts/02_make_masks.py). Пропускает плотные поля
#                    кокков целиком: ~75 из 400 «пустых» патчей на деле покрыты клетками на 5–40%;
#   omnipose       — Omnipose bact_phase_omni, модель для бактерий (scripts/02b_make_masks_omnipose.py);
#                    находит такие поля и одиночные бледные клетки, но размечает мелкий шум;
#   omnipose_clean — omnipose без объектов < REFERENCE_MIN_AREA пикселей (scripts/02c_compare_references.py).
#                    Основной эталон (решение по итогам визуальной проверки, reports/reference_comparison.md).
# Выбирается переменной окружения IMBP_REFERENCE; маски лежат в img_XXXX_mask.png.
REFERENCE_MASK_DIRS = {
    "cellpose": DATA_DIR / "train_subset_masks",
    "omnipose": DATA_DIR / "train_subset_masks_omnipose",
    "omnipose_clean": DATA_DIR / "train_subset_masks_omnipose_clean",
}
REFERENCE_MIN_AREA = 30
REFERENCE = os.environ.get("IMBP_REFERENCE", "omnipose_clean")
SUBSET_MASKS_DIR = REFERENCE_MASK_DIRS[REFERENCE]

# Генерируемые файлы внутри imbp/ (CSV обучения зависят от эталона — отдельная папка на каждый).
ARTIFACTS_DIR = PROJECT_ROOT / "artifacts" / REFERENCE   # промежуточные CSV обучения
MODELS_DIR = PROJECT_ROOT / "models"         # обученные модели
REPORTS_DIR = PROJECT_ROOT / "reports"       # метрики и рисунки

IOU_GRID_CSV = ARTIFACTS_DIR / "iou_grid.csv"                  # IoU для каждой пары (K, M) и каждого патча
OPTIMAL_PARAMS_CSV = ARTIFACTS_DIR / "optimal_parameters.csv"  # лучшая пара (K, M) для каждого патча
TRAINING_DATA_CSV = ARTIFACTS_DIR / "training_data.csv"        # признаки + целевые K, M

MODEL_PATH = Path(os.environ.get("IMBP_MODEL_PATH", MODELS_DIR / "slic_params_rf.joblib"))
OBJECT_FILTER_PATH = Path(os.environ.get("IMBP_OBJECT_FILTER_PATH", MODELS_DIR / "object_filter_rf.joblib"))
METHOD_CHOOSER_PATH = Path(os.environ.get("IMBP_METHOD_CHOOSER_PATH", MODELS_DIR / "method_chooser_rf.joblib"))

# ---------------------------------------------------------------------------
# Общие настройки воспроизводимости
# ---------------------------------------------------------------------------

RANDOM_STATE = 42   # фиксированный seed (как в курсовой) — одинаковое разбиение train/test
TEST_SIZE = 0.2     # 80% / 20% (320 / 80 изображений)

# ---------------------------------------------------------------------------
# Нарезка снимков на патчи (раздел 4.1 курсовой)
# ---------------------------------------------------------------------------

PATCH_ROWS = 3   # снимок 1616×1216 режется на 3 строки ...
PATCH_COLS = 4   # ... и 4 столбца -> патчи ≈ 404×405 пикселей

# Размер «обучающего» патча (высота, ширина). RF предсказывает АБСОЛЮТНОЕ число суперпикселей K
# для патча такого размера, поэтому большие снимки при инференсе режутся на тайлы примерно этого
# размера (см. segmentation/slic.py). Это убирает рассогласование «обучали на патчах — применяем
# к полному снимку».
TILE_SIZE = (405, 404)

# ---------------------------------------------------------------------------
# Фон и красители (stains.py)
# ---------------------------------------------------------------------------

BACKGROUND_SCALE = 4      # фон оценивается на копии, уменьшенной в 4 раза (фон гладкий — так быстрее)
BACKGROUND_KERNEL = 121   # ядро морфологического закрытия, пикселей исходного снимка (> размера скоплений)

OD_DISPLAY_MAX = 1.5                   # суммарная OD, соответствующая 255 в канале «плотность красителя»

# ---------------------------------------------------------------------------
# Маска Оцу (бинаризация «бактерии / фон»)
# ---------------------------------------------------------------------------

# Канал, по которому строится порог Оцу:
#   "gray"      — яркость (как в курсовой);
#   "flat_gray" — яркость после выравнивания фона;
#   "od"        — суммарная оптическая плотность красителей относительно локального фона.
# Выбор по CV на не-тестовых патчах (эталон omnipose_clean, MIoU по 720 патчам):
#   gray 51.9%, flat_gray 55.8%, od 53.7% — выравнивание фона убирает пятна и виньетирование.
MASK_CHANNEL = "flat_gray"

# Размер ядра гауссова размытия перед порогом Оцу (подавляет шум матрицы камеры).
OTSU_BLUR_KSIZE = 5

# Минимальное расстояние (в уровнях яркости 0..255) между средними классов Оцу.
# Если на патче нет бактерий, Оцу всё равно делит однородный фон «пополам» по шуму —
# получается ложная маска на ~50% площади. Если классы различаются слабее этого порога,
# считаем, что на изображении бактерий нет. Подобрано по 800 размеченным патчам (400 пустых по
# Cellpose + 400 с бактериями): при 15 верно отбраковывается ~52% пустых патчей и теряется ~13%
# непустых (обычно с единичными бледными клетками); MIoU по всем патчам растёт с 0.24 до 0.48.
# Этап 2 (канал flat_gray, эталон omnipose_clean): оптимум по CV — 17.5; верно отбраковывается 84%
# пустых патчей.
OTSU_MIN_CLASS_GAP = 17.5

# Объекты маски Оцу меньше этой площади (пиксели) считаются пылью и удаляются.
OTSU_MIN_OBJECT_AREA = 15

# ---------------------------------------------------------------------------
# SLIC (раздел 4.1)
# ---------------------------------------------------------------------------

# Дискретная сетка параметров — классы для RandomForestClassifier (таблица 1 курсовой).
K_VALUES = (50, 150, 300, 500, 750, 1000)   # число суперпикселей (n_segments)
M_VALUES = (5, 10, 15, 20, 30, 45)          # компактность (compactness)
SLIC_ITERATIONS = 10                        # фиксированное число итераций (max_num_iter)

# Суперпиксель относится к бактериям, если доля «бактериальных» пикселей в нём больше порога.
# Голосование идёт по маске Оцу (в ПО) или по эталону Cellpose (только для оценки «потолка»).
SUPERPIXEL_VOTE_THRESHOLD = 0.5

# Параметры по умолчанию, если обученная модель недоступна и аналитика тоже отключена.
DEFAULT_K = 300
DEFAULT_M = 15

# ---------------------------------------------------------------------------
# GMM с пространственной регуляризацией (раздел 4.2)
# ---------------------------------------------------------------------------

GMM_N_COMPONENTS = 3            # фон / микроорганизмы / артефакты
GMM_COVARIANCE_TYPE = "tied"
GMM_BILATERAL_D = 9             # двусторонний фильтр: диаметр окрестности
GMM_BILATERAL_SIGMA_COLOR = 75
GMM_BILATERAL_SIGMA_SPACE = 75
GMM_BILATERAL = True           # применять ли двусторонний фильтр перед GMM
# Вес потенциала Поттса в HMRF (0 — без HMRF, как в курсовой). Проверено по CV (720 патчей,
# эталон omnipose_clean): β = 0 / 3 / 10 / 30 -> MIoU 49.1 / 49.2 / 49.3 / 49.2% с bilateral и
# 48.3 / 47.7 / 47.6 / 48.0% без него. Апостериорные вероятности GMM почти 0/1, и сглаживание
# Поттса почти ничего не меняет; bilateral-фильтр сглаживает лучше. Поэтому по умолчанию выключено.
GMM_HMRF_BETA = 0.0
GMM_HMRF_ITERS = 5             # число итераций ICM
GMM_FIT_SAMPLE = 20_000         # EM обучается на случайной подвыборке пикселей (ускорение в разы),
                                # предсказание делается для всех пикселей
# Какие кластеры считаются бактериями (кластеры отсортированы по яркости: 0 — самый тёмный).
# Правило: кластеры из GMM_BACTERIA_CLUSTERS — всегда; остальные (кроме самого светлого = фон)
# добавляются, если занимают меньше GMM_EXTRA_CLUSTER_MAX_FRACTION площади снимка. Мелкий средний
# кластер — это клетки другого цвета (например, бледные красные Грам(−) рядом с тёмными
# фиолетовыми Грам(+)), а крупный — градиент фона / пятно красителя.
# Подобрано по MIoU с эталоном (scripts/06_evaluate.py): train 44.3%, test 47.5%; для сравнения
# только (0,) — 42.2% / 40.6%, (0, 1) — 35.0% / 38.7%, (1,) как в исходном step12/13 — 13.8% / 15.8%.
GMM_BACTERIA_CLUSTERS = (0,)
GMM_EXTRA_CLUSTER_MAX_FRACTION = 0.05
GMM_MIN_AREA = 50               # компоненты связности меньше этой площади удаляются (аппроксимация HMRF)

# ---------------------------------------------------------------------------
# Фильтр ложных объектов и режим «Авто» (этап 2)
# ---------------------------------------------------------------------------

USE_OBJECT_FILTER = True   # удалять компоненты маски, которые RF считает артефактами (object_filter.py)

# ---------------------------------------------------------------------------
# Морфологическая классификация (раздел 4.3)
# ---------------------------------------------------------------------------

# Разделение маски на отдельные клетки (instances.py): маркерный водораздел по h-максимумам рельефа
# «расстояние до границы + β·тёмность» и склейка кусков с широким контактом. Подобрано перебором по меткам
# отдельных клеток Omnipose на 720 не-тестовых патчах (scripts/10_tune_instances.py, reports/instances.md):
# F1 по клеткам 0.79 против 0.54 у водораздела этапа 1 и 0.36 у компонент связности.
INSTANCE_H = 1.5            # минимальная «высота» вершины над седлом, чтобы считаться отдельной клеткой (px)
INSTANCE_SIGMA = 0.5        # сглаживание рельефа (px)
INSTANCE_BETA = 0.2         # вес тёмности (px рельефа на уровень яркости): тёмный центр клетки = вершина
# Склеивать соседей, если контакт > доля × диаметр меньшего. По CV 1.0 и 0 равны (F1 0.7855); из равных
# скрипт берёт наибольшее значение — защита от разрезания крупных вытянутых клеток поперёк.
INSTANCE_NECK_RATIO = 1.0

NOISE_MIN_AREA = 15             # объекты меньше (пиксели) — шум/артефакт
ECCENTRICITY_THRESHOLD = 0.70   # e < 0.7 -> кокк, иначе бацилла (эмпирический порог курсовой)
# Уверенный «центр» клетки: distance > доля * max(distance) внутри объекта. В step12 было 0.3 от
# ГЛОБАЛЬНОГО максимума; при 0.3 касающиеся кокки не разделяются (перешеек толще 0.3 радиуса).
# 0.5 разделяет диплококки и не дробит палочки (проверено на снимках E. coli, Staph., Corynebact.).
WATERSHED_FG_FRACTION = 0.5
WATERSHED_MIN_AREA = 30         # объекты меньше этой площади не разрезаются водоразделом

# Окраска по Граму: Грам(+) — фиолетовые, Грам(−) — красные/розовые.
#   "od_red" — доля оптической плотности объекта в красном канале > GRAM_OD_RED_SHARE -> Грам(+)
#              (кристаллический фиолетовый поглощает красный свет, сафранин — нет);
#   "rgb"    — правило курсовой: средний R > среднего B + GRAM_RED_DELTA -> Грам(−).
# Проверка на 203 снимках тест-культур с известным Грамом (по названию файла; 180 «+», 23 «−»):
# сбалансированная точность "od_red" — 0.86 (0.85 по CV), "rgb" — 0.58 (Грам(+) верно лишь в 15%).
GRAM_RULE = "od_red"
GRAM_OD_RED_SHARE = 0.12
GRAM_RED_DELTA = 15.0

# ---------------------------------------------------------------------------
# Признаки для Random Forest (раздел 4.1). Порядок важен — он зашит в обученную модель.
# ---------------------------------------------------------------------------

FEATURE_NAMES = ("brightness", "contrast", "entropy", "otsu_thresh", "density", "avg_size")
